  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
});

test('dashboard with partial payments', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(issued);
