test('dashboard with large amounts', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1000 }],
  }).value;

  const issued = issueInvoice(draft, []).value;
  issued.dueDate = '2024-02-14';

