import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee, dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

// Helper to create an issued invoice with a specific due date
function createIssuedWithDueDate(customerId = 'C-001', issueDate = '2024-01-15', dueDate = '2024-02-14') {
  const created = createInvoice({
    customerId,
    issueDate,
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  }).value;
  const issued = issueInvoice(created, []).value;
  // Manually set dueDate for testing (in real use, terms would be set)
  return {
    ...issued,
    dueDate,
  };
}

test('overdueInvoices returns invoices with dueDate before asOf', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const result = overdueInvoices([invoice], '2024-02-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const result = overdueInvoices([invoice], '2024-02-14');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-20');
  const result = overdueInvoices([invoice], '2024-02-14');

  assert.equal(result.length, 0);
});

test('overdueInvoices filters by status (issued only)', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  draft.dueDate = '2024-02-14';

  const result = overdueInvoices([issued, draft], '2024-02-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-15' }).value;

  const result = overdueInvoices([partial], '2024-02-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices excludes paid invoices', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2024-02-15' }).value;

  const result = overdueInvoices([paid], '2024-02-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const result = overdueInvoices([invoice], '2024-02-20');

  // 2024-02-20 minus 2024-02-14 = 6 days
  assert.equal(result[0].daysOverdue, 6);
});

test('overdueInvoices calculates due amount from balanceDue', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-15' }).value;
  const totals = invoiceTotals(partial);

  const result = overdueInvoices([partial], '2024-02-20');

  const expectedDue = totals.total - 5000;
  assert.equal(result[0].due, expectedDue);
});

test('overdueInvoices sorts by daysOverdue (most overdue first)', () => {
  const invoice1 = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const invoice2 = createIssuedWithDueDate('C-002', '2024-01-20', '2024-02-19');
  const invoice3 = createIssuedWithDueDate('C-003', '2024-01-10', '2024-02-09');

  const result = overdueInvoices([invoice1, invoice2, invoice3], '2024-02-20');

  assert.equal(result.length, 3);
  // invoice3: 2024-02-20 - 2024-02-09 = 11 days (most overdue)
  // invoice1: 2024-02-20 - 2024-02-14 = 6 days
  // invoice2: 2024-02-20 - 2024-02-19 = 1 day (least overdue)
  assert.equal(result[0].daysOverdue, 11);
  assert.equal(result[1].daysOverdue, 6);
  assert.equal(result[2].daysOverdue, 1);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-20');
  const result = overdueInvoices([invoice], '2024-02-14');

  assert.equal(result.length, 0);
  assert.ok(Array.isArray(result));
});

test('overdueInvoices includes all required fields', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const result = overdueInvoices([invoice], '2024-02-20');

  const overdue = result[0];
  assert.ok(overdue.number);
  assert.ok(overdue.customerId);
  assert.ok(overdue.dueDate);
  assert.equal(typeof overdue.daysOverdue, 'number');
  assert.equal(typeof overdue.due, 'number');
});

test('overdueInvoices handles multiple customers', () => {
  const invoice1 = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const invoice2 = createIssuedWithDueDate('C-002', '2024-01-15', '2024-02-14');
  const invoice3 = createIssuedWithDueDate('C-003', '2024-01-15', '2024-02-14');

  const result = overdueInvoices([invoice1, invoice2, invoice3], '2024-02-20');

  assert.equal(result.length, 3);
  assert.ok(result.some(r => r.customerId === 'C-001'));
  assert.ok(result.some(r => r.customerId === 'C-002'));
  assert.ok(result.some(r => r.customerId === 'C-003'));
});

test('overdueInvoices does not mutate input invoices', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const originalNumber = invoice.number;
  const originalStatus = invoice.status;

  overdueInvoices([invoice], '2024-02-20');

  assert.equal(invoice.number, originalNumber);
  assert.equal(invoice.status, originalStatus);
});

test('overdueInvoices with large date difference', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-01', '2024-01-05');
  const result = overdueInvoices([invoice], '2024-12-31');

  assert.equal(result.length, 1);
  // 2024-12-31 minus 2024-01-05 = 361 days (2024 is leap year)
  assert.equal(result[0].daysOverdue, 361);
});

test('overdueInvoices year boundary', () => {
  const invoice = createIssuedWithDueDate('C-001', '2023-12-15', '2023-12-31');
  const result = overdueInvoices([invoice], '2024-01-15');

  assert.equal(result.length, 1);
  // 2024-01-15 minus 2023-12-31 = 15 days
  assert.equal(result[0].daysOverdue, 15);
});

test('overdueInvoices mixed statuses', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2024-02-15' }).value;
  paid.dueDate = '2024-02-14';

  const partial = createIssuedWithDueDate('C-002', '2024-01-15', '2024-02-14');
  const partial2 = recordPayment(partial, { amount: 5000, date: '2024-02-15' }).value;

  const result = overdueInvoices([issued, paid, partial2], '2024-02-20');

  // Should include issued and partially_paid, exclude paid
  assert.equal(result.length, 2);
  assert.ok(result.some(r => r.customerId === 'C-001'));
  assert.ok(result.some(r => r.customerId === 'C-002'));
});

test('overdueInvoices with empty array', () => {
  const result = overdueInvoices([], '2024-02-20');

  assert.equal(result.length, 0);
  assert.ok(Array.isArray(result));
});

test('vatSummary returns empty array for no applicable invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const result = vatSummary([draft]);

  assert.equal(result.length, 0);
});

test('vatSummary returns summary for issued invoice', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');

  const result = vatSummary([invoice]);

  assert.equal(result.length, 1);
  assert.ok(result[0].rate);
  assert.ok(result[0].base);
  assert.ok(result[0].vat);
});

test('vatSummary includes partially_paid invoices', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-15' }).value;

  const result = vatSummary([partial]);

  assert.equal(result.length, 1);
  assert.ok(result[0].base > 0);
});

test('vatSummary includes paid invoices', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2024-02-15' }).value;

  const result = vatSummary([paid]);

  assert.equal(result.length, 1);
  assert.ok(result[0].base > 0);
});

test('vatSummary excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = createIssuedWithDueDate();

  const result = vatSummary([draft, issued]);

  assert.equal(result.length, 1);
  assert.ok(result[0].base > 0);
});

test('vatSummary handles multiple VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },    // 21% VAT
      { sku: 'PRINT-A4', qty: 10 },   // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 3);
  assert.ok(result.some(r => r.rate === 21));
  assert.ok(result.some(r => r.rate === 9));
  assert.ok(result.some(r => r.rate === 0));
});

test('vatSummary sorts by rate descending', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },     // 21% VAT
      { sku: 'PRINT-A4', qty: 10 },    // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);
});

test('vatSummary calculates base as line total minus discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 }, // 8500 - 850 = 7650 base
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  // DES-HOUR is 8500 cents, with 10% discount = 850, base = 7650
  assert.equal(result[0].base, 7650);
});

test('vatSummary calculates VAT on discounted base', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  // DES-HOUR is 8500 cents, explicit 0% discount overrides tier, so base = 8500
  // VAT is 8500 * 21% = 1785
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 8500);
  assert.equal(result[0].vat, 1785);
});

test('vatSummary aggregates multiple invoices with same rate', () => {
  const invoice1 = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const invoice2 = createIssuedWithDueDate('C-002', '2024-01-20', '2024-02-19');

  const result = vatSummary([invoice1, invoice2]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Both invoices have same line, so base and VAT should be doubled
  assert.ok(result[0].base > 0);
  assert.ok(result[0].vat > 0);
});

test('vatSummary aggregates rates correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },     // 21% VAT
      { sku: 'DES-HOUR', qty: 1 },     // 21% VAT again
      { sku: 'PRINT-A4', qty: 5 },     // 9% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  const rate21 = result.find(r => r.rate === 21);
  const rate9 = result.find(r => r.rate === 9);
  assert.ok(rate21.base > 0);
  assert.ok(rate9.base > 0);
});

test('vatSummary with vouchers (vouchers do not affect VAT)', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const withVoucher = applyVoucher(draft, { code: 'TEST', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const result = vatSummary([issued]);

  // VAT is calculated on the base (after line discounts), not affected by voucher
  assert.equal(result.length, 1);
  assert.ok(result[0].vat > 0);
});

test('vatSummary returns empty array for empty invoices list', () => {
  const result = vatSummary([]);

  assert.equal(result.length, 0);
  assert.ok(Array.isArray(result));
});

test('vatSummary with zero VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 0);
  assert.equal(result[0].vat, 0);
  assert.ok(result[0].base > 0);
});

test('vatSummary does not mutate invoices', () => {
  const invoice = createIssuedWithDueDate();
  const originalStatus = invoice.status;
  const originalLines = JSON.stringify(invoice.lines);

  vatSummary([invoice]);

  assert.equal(invoice.status, originalStatus);
  assert.equal(JSON.stringify(invoice.lines), originalLines);
});

test('vatSummary includes all required fields', () => {
  const invoice = createIssuedWithDueDate();
  const result = vatSummary([invoice]);

  assert.ok(result[0].rate !== undefined);
  assert.ok(result[0].base !== undefined);
  assert.ok(result[0].vat !== undefined);
  assert.equal(typeof result[0].rate, 'number');
  assert.equal(typeof result[0].base, 'number');
  assert.equal(typeof result[0].vat, 'number');
});

test('lateFee returns 0 for invoice not yet due', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');

  const fee = lateFee(invoice, '2024-02-14');

  assert.equal(fee, 0);
});

test('lateFee returns 0 for invoice due in the future', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-20');

  const fee = lateFee(invoice, '2024-02-14');

  assert.equal(fee, 0);
});

test('lateFee calculates fee for 1 day overdue', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(invoice);

  const fee = lateFee(invoice, '2024-02-15');

  // Fee = total * 1 day * 0.04% = total * 0.0004
  const expectedFee = Math.round(totals.total * 1 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee calculates fee for multiple days overdue', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(invoice);

  const fee = lateFee(invoice, '2024-02-24');

  // 10 days overdue
  // Fee = total * 10 * 0.04% = total * 0.004
  const expectedFee = Math.round(totals.total * 10 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee uses balanceDue not invoice total', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-15' }).value;
  const totals = invoiceTotals(partial);
  const due = totals.total - 5000;

  const fee = lateFee(partial, '2024-02-24');

  // 10 days overdue on remaining balance
  const expectedFee = Math.round(due * 10 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee rounds fractional cents', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');

  const fee = lateFee(invoice, '2024-02-15');

  // Fee should be rounded
  assert.equal(typeof fee, 'number');
  assert.equal(Number.isInteger(fee), true);
});

test('lateFee with zero balance due', () => {
  const issued = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2024-02-15' }).value;

  const fee = lateFee(paid, '2024-02-24');

  // No balance due, so no late fee
  assert.equal(fee, 0);
});

test('lateFee with large day difference', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-01', '2024-01-05');
  const totals = invoiceTotals(invoice);

  const fee = lateFee(invoice, '2024-12-31');

  // 361 days overdue (from Jan 5 to Dec 31 in leap year)
  const expectedFee = Math.round(totals.total * 361 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee returns positive number', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');

  const fee = lateFee(invoice, '2024-02-20');

  assert.ok(fee >= 0);
});

test('lateFee increases with more days overdue', () => {
  const invoice = createIssuedWithDueDate('C-001', '2024-01-15', '2024-02-14');

  const fee5days = lateFee(invoice, '2024-02-19');
  const fee10days = lateFee(invoice, '2024-02-24');

  assert.ok(fee10days > fee5days);
});

test('lateFee across year boundary', () => {
  const invoice = createIssuedWithDueDate('C-001', '2023-12-15', '2023-12-31');
  const totals = invoiceTotals(invoice);

  const fee = lateFee(invoice, '2024-01-15');

  // 15 days overdue
  const expectedFee = Math.round(totals.total * 15 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee with vouchers applied', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const withVoucher = applyVoucher(draft, { code: 'TEST', amount: 2000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  issued.dueDate = '2024-02-14';

  const fee = lateFee(issued, '2024-02-20');

  // Fee is based on balance due (after voucher)
  assert.ok(fee > 0);
});

test('lateFee does not mutate invoice', () => {
  const invoice = createIssuedWithDueDate();
  const originalDueDate = invoice.dueDate;

  lateFee(invoice, '2024-02-20');

  assert.equal(invoice.dueDate, originalDueDate);
});
